### 一、缓存一致性要求

**为什么：** 车辆位置是高频变化的数据，用户查询的是“周边可用车辆数”，这是一个近似值（比如 0.5 公里内的空闲车辆）。即使数据滞后几秒，用户感知差异不大，对**最终一致性**可接受。如果要求强一致性，每次查询都得从数据库实时聚合，延迟和压力都不可控。

**怎么做：**
- 采用 **弱一致性 + TTL 过期**：每个区域的缓存设置合理的过期时间（如 5~10 秒），超时后自动失效，下次查询回源数据库重新计算。
- 结合 **版本号或时间戳**：当车辆状态变更时，异步更新缓存并带上时间戳，查询时对比时间戳，若缓存版本落后于最新版本则回源。

---

### 二、定时刷新 vs 事件驱动

**为什么：** 两者各有优缺点。定时刷新（例如每 5 秒全量拉取）实现简单，但会浪费资源（无车辆变化时也刷新）；事件驱动（车辆位置上报时实时更新对应区域）更精准，但处理瞬时高并发时可能造成缓存击穿。

**怎么做：**  
我倾向于 **事件驱动为主，定时刷新为辅** 的组合策略：
- **事件驱动更新**：车辆每 N 秒上报 GPS 时，通过 MQ 触发区域运力数的增量更新（如只更新该区域的总空闲数，不用全量聚合）。这样做响应快，数据新鲜。
- **定时刷新兜底**：对每个区域额外启动一个低频率定时任务（如每 30 秒），周期性从数据库拉取全量数据覆盖缓存。这可以纠正事件驱动可能累积的误差（比如车辆离线超时未上报），同时作为限流缓冲。

**代码示例（伪代码）：**
```java
// 事件驱动：车辆上报时
void onVehicleReport(LocationReport report) {
    String region = geoHash(report.lat, report.lng);
    if (report.isOnline && isAvailable) {
        redis.incr("region:count:" + region);
    } else {
        redis.decr("region:count:" + region);
    }
}

// 定时刷新：每 30 秒执行一次
@Scheduled(fixedDelay = 30000)
void refreshAllRegions() {
    Map<String, Integer> realCounts = db.queryRegionCounts();
    redis.setAll(realCounts, 30, TimeUnit.SECONDS);
}
```

