### 三、缓存宕机如何降级

**为什么：** 缓存宕机后，如果所有查询直接穿透到数据库，可能引发数据库雪崩。需要保证核心功能（展示车辆数量）仍然可用，但允许数据稍微陈旧或精确度下降。

**怎么做：** 多级降级策略：
1. **本地缓存（客户端级）**：在应用服务器内存中维护一个简版缓存（例如 1 秒内的旧数据），使用一个短 TTL。当 Redis 不可用时，直接返回本地缓存数据。本地缓存可用 Guava Cache 或 Caffeine。
2. **静态默认值降级**：如果本地缓存也没有（例如刚启动），返回一个保守值（如 0 或基于历史统计的均值），并打点告警。
3. **熔断限流**：使用 Sentinel/Hystrix 对数据库查询接口做限流，只允许部分请求穿透，其余快速失败返回本地缓存。
4. **最终兜底**：如果所有缓存都失效且限流已满，直接返回 “数据加载中” 或前端展示上次缓存值（客户端本地存储）。

**关键点：** 降级后必须通过监控系统告警，并尽快恢复缓存集群，同时避免降级逻辑自身成为性能瓶颈。'),
